-- SysxHub branding
pcall(function()
    local CoreGui = (gethui and gethui()) or game:GetService("CoreGui")
    if CoreGui:FindFirstChild("SysxHubBranding") then
        CoreGui.SysxHubBranding:Destroy()
    end

    local gui = Instance.new("ScreenGui")
    gui.Name = "SysxHubBranding"
    gui.ResetOnSpawn = false
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.Parent = CoreGui

    local frame = Instance.new("Frame")
    frame.Name = "Header"
    frame.Size = UDim2.new(0, 190, 0, 58)
    frame.Position = UDim2.new(0, 12, 0, 12)
    frame.BackgroundTransparency = 0.12
    frame.BackgroundColor3 = Color3.fromRGB(18, 18, 24)
    frame.BorderSizePixel = 0
    frame.Parent = gui

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 10)
    corner.Parent = frame

    local logo = Instance.new("ImageLabel")
    logo.Name = "Logo"
    logo.BackgroundTransparency = 1
    logo.Size = UDim2.new(0, 42, 0, 42)
    logo.Position = UDim2.new(0, 8, 0.5, -21)
    logo.Image = "rbxassetid://70792832229220"
    logo.Parent = frame

    local text = Instance.new("TextLabel")
    text.Name = "Title"
    text.BackgroundTransparency = 1
    text.Position = UDim2.new(0, 58, 0, 0)
    text.Size = UDim2.new(1, -65, 1, 0)
    text.Font = Enum.Font.GothamBold
    text.Text = "SysxHub"
    text.TextColor3 = Color3.fromRGB(255, 255, 255)
    text.TextSize = 21
    text.TextXAlignment = Enum.TextXAlignment.Left
    text.Parent = frame
end)

